import{_ as p,o,c as n,a5 as s}from"./chunks/framework.Cooo9kuv.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"794-批量删除文件及文件名中（）括号中内容及括号、空格、标点符号","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["批量删除名称中括号","批量删除名称中标点","批量删除名称中空格"]},"headers":[],"relativePath":"md/文件及文件夹批处理/794-批量删除文件及文件名中（）括号中内容及括号、空格、标点符号.md","filePath":"md/文件及文件夹批处理/794-批量删除文件及文件名中（）括号中内容及括号、空格、标点符号.md"}'),_={name:"md/文件及文件夹批处理/794-批量删除文件及文件名中（）括号中内容及括号、空格、标点符号.md"};function g(r,t,a,e,c,w){return o(),n("div",null,[...t[0]||(t[0]=[s('<p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250309170722174151124232424.png" alt=""></p><p>批量删除文件及文件名中（）括号中内容及括号、空格、标点符号</p><p>1、可以单独删除文件及文件夹名中空格、标点符号</p><p>2、可以同时删除文件及文件夹命中括号，括号类型如下：对随意组合的括号同样有效，比如【）这样的括号组合</p><p>[()[]{}〈〉「」【】〖〗《》〔〕].*?[()[]{}〈〉「」【】〖〗《》〔〕]</p><p>3、标点符号批量删除，选择选项后如下所示的符号在识别到后会自动删除<br> ！？｡。＂＃＄％＆＇（）＊＋，－／：；＜＝＞＠［＼］＾＿｀｛｜｝～｟｠｢｣､、〃》「」『』【】〔〕〖〗〘〙〚〛〜〝〞〟〰〾〿–—‘’‛“”„‟…‧﹏.]</p><p>4、同时处理文件及文件夹时，序列_1 _2 _3.....这样的序列会自动穿透子文件夹连续。</p><p><strong>选择文件时只处理文件，选择文件及文件夹时同时处理文件及文件夹.....</strong></p><p><strong>如果只选择文件和文件夹，或单独选择文件或文件夹，则只删除文件及文件夹名中的括号及括号内的内容</strong></p><p><strong>同名文件处理方式有两种：</strong></p><p>1、自动添加 _1  _2  _3  ...这样的序列</p><p>2、不进行重命名，如果文件或文件夹格式如下图所示</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250309162304174150858458614.png" alt=""></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250309162323174150860320060.png" alt=""></p><p>只会修改一个文件或文件夹名，其他去除括号后如果出现同名则不进行重命名操作。</p><p><strong>效果演示</strong></p><p><strong>文件夹演示，如下图所示原来的文件夹名是这样</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250309170803174151128335320.png" alt=""></p><p>处理后的文件夹名如下图所示</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250309170834174151131492584.png" alt=""></p><p><strong>文件演示</strong></p><p>处理前的文件名如下图所示</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250309170922174151136284559-1.png" alt=""></p><p>处理后的文件名如下图所示</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250309170953174151139354152.png" alt=""></p><p><strong>程序下载</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1597.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1597.html</a></p>',28)])])}const d=p(_,[["render",g]]);export{l as __pageData,d as default};
